(function(){(()=>{"use strict";const e=(n,a,o,i,s,r,t)=>({g:n,p:a,n:o,f:i,how:s,ex:r,...t?{fig:t}:{}});window.PhysicaRankAtomsJee={chapter:"Atoms and Nuclei",secs:["Rutherford model and alpha scattering","Bohr model of hydrogen","Hydrogen spectrum","Energy levels and transitions","Nucleus: composition and size","Mass defect and binding energy","Fission and fusion","Radioactivity and decay law"],table:[["Planck constant h","ML\xB2T\u207B\xB9 (J s)"],["Angular momentum L = nh/2\u03C0","ML\xB2T\u207B\xB9"],["Bohr radius a\u2080","L (metre)"],["Rydberg constant R","L\u207B\xB9 (m\u207B\xB9)"],["Energy of a level, binding energy","ML\xB2T\u207B\xB2 (J or eV, MeV)"],["Nuclear radius R\u2080","L (femtometre, 1 fm = 10\u207B\xB9\u2075 m)"],["Mass defect \u0394m","M (u or kg)"],["Nuclear density","ML\u207B\xB3 (kg/m\xB3)"],["Decay constant \u03BB","T\u207B\xB9 (s\u207B\xB9)"],["Half-life T and mean life \u03C4","T (second)"],["Activity A = \u03BBN","T\u207B\xB9 (becquerel = s\u207B\xB9)"],["Orbital magnetic moment \u03BC","L\xB2A (A m\xB2)"]],formulas:[e("Rutherford model and alpha scattering",1,"Thomson and Rutherford models","Thomson: a positive sphere of radius about 10\u207B\xB9\u2070 m with electrons embedded in it \xB7 Rutherford (Geiger and Marsden, \u03B1 rays on gold foil): most \u03B1 particles go straight through, a few are scattered through large angles, about 1 in 8000 turns back \xB7 so the positive charge and nearly all the mass sit in a tiny nucleus of size about 10\u207B\xB9\u2075 m \xB7 atom size about 10\u207B\xB9\u2070 m \xB7 the electrons move around the nucleus \xB7 failures: an electron going round a nucleus should radiate and spiral in, and the model cannot explain the line spectrum","Link every observation with a conclusion: straight through means mostly empty space; large angle means a small, heavy, positive centre; back-scattering means a single strong repulsion.","If the atom were 100 m wide the nucleus would be 100 \xD7 10\u207B\u2075 m = 1 mm across.","anscat"),e("Rutherford model and alpha scattering",1,"Distance of closest approach","head-on, the \u03B1 particle stops where all its kinetic energy has become electric potential energy: K = {1;4\u03C0\u03B5\u2080}{(2e)(Ze);r\u2080} \xB7 r\u2080 = {2Ze\xB2;4\u03C0\u03B5\u2080K} = {2Z \xD7 1.44 MeV fm;K in MeV} \xB7 r\u2080 \u221D {1;K} \u221D {1;v\xB2} \xB7 for a proton of the same K the distance is half, since its charge is e instead of 2e","Write K = kq\u2081q\u2082/r\u2080 and solve. If the speed is doubled, K becomes four times and r\u2080 becomes one fourth. A heavier projectile with the same K does not change r\u2080; only its charge does.","A 5 MeV \u03B1 particle on gold (Z = 79): r\u2080 = 2 \xD7 79 \xD7 1.44 \xF7 5 = 45.5 fm, much larger than the nuclear radius of gold (about 7 fm).","anscat"),e("Rutherford model and alpha scattering",1,"Impact parameter and angle of scattering","b = {r\u2080;2} cot{\u03B8;2} = {kq\u2081q\u2082;2K} cot{\u03B8;2} \xB7 b = 0 gives \u03B8 = 180\xB0 (the \u03B1 particle returns along its path) \xB7 \u03B8 = 90\xB0 gives b = {r\u2080;2} \xB7 a large b gives a small \u03B8 \xB7 b is the perpendicular distance from the nucleus to the original line of motion","Find r\u2080 first and then use b = (r\u2080/2) cot(\u03B8/2). The smaller the impact parameter, the larger the deflection.","Same 5 MeV \u03B1 on gold, \u03B8 = 90\xB0: b = 45.5 \xF7 2 = 22.8 fm.","anscat"),e("Rutherford model and alpha scattering",2,"Number of particles scattered","N(\u03B8) \u221D {1;sin\u2074(\u03B8/2)} \xB7 N \u221D Z\xB2 \xB7 N \u221D foil thickness \xB7 N \u221D {1;K\xB2} \xB7 very few particles are scattered at large angles, most at small angles \xB7 \u03B1 particles of 5 MeV to 8 MeV are used, so that they reach the nucleus","Take the ratio of the two values of sin\u2074(\u03B8/2). Do not add the other factors if they are the same for both angles.","N\u2086\u2080 \xF7 N\u2081\u2082\u2080 = sin\u207460\xB0 \xF7 sin\u207430\xB0 = 0.5625 \xF7 0.0625 = 9, so nine times as many \u03B1 particles are counted at 60\xB0 as at 120\xB0.","anscat"),e("Bohr model of hydrogen",1,"Postulates of Bohr","an electron moves in certain stationary circular orbits without radiating \xB7 the Coulomb force gives the centripetal force: {mv\xB2;r} = {kZe\xB2;r\xB2} \xB7 the angular momentum is quantised: mvr = {nh;2\u03C0} (n = 1, 2, 3 \u2026) \xB7 radiation is emitted or absorbed only in a jump between two orbits: hf = Ei \u2212 Ef \xB7 valid only for one-electron species: H, He\u207A, Li\xB2\u207A \xB7 it fails for atoms with more electrons and does not explain the fine structure or the intensity of lines","Combine the two equations (force and angular momentum) to get r, v and E. Do not use the postulates for helium atom or lithium atom.","The angular momentum in n = 3 is 3h \xF7 2\u03C0 = 3 \xD7 6.63 \xD7 10\u207B\xB3\u2074 \xF7 6.28 = 3.17 \xD7 10\u207B\xB3\u2074 J s.","anorb"),e("Bohr model of hydrogen",1,"Radius of the nth orbit","r\u2099 = a\u2080{n\xB2;Z} \xB7 a\u2080 = {\u03B5\u2080h\xB2;\u03C0me\xB2} = 0.529 \xC5 \xB7 r\u2099 \u221D {n\xB2;Z} \xB7 radii of hydrogen in the ratio 1 : 4 : 9 : 16 \xB7 r\u2081 of hydrogen = 0.529 \xC5, of He\u207A = 0.265 \xC5, of Li\xB2\u207A = 0.176 \xC5","Put in the numbers a\u2080 = 0.529 \xC5, n and Z. For ratios write r\u2099 \u221D n\xB2/Z only.","Li\xB2\u207A in n = 2: r = 0.529 \xD7 4 \xF7 3 = 0.705 \xC5. Hydrogen in n = 3: r = 0.529 \xD7 9 = 4.76 \xC5.","anorb"),e("Bohr model of hydrogen",1,"Speed in the nth orbit","v\u2099 = {Ze\xB2;2\u03B5\u2080hn} = 2.19 \xD7 10\u2076 {Z;n} m/s = {Z;n}\u03B1c with \u03B1 = {1;137} \xB7 v\u2099 \u221D {Z;n} \xB7 in hydrogen the speed in n = 1 is c \xF7 137 \xB7 the speed is much lower than c, so no relativity is needed","The speed is the quickest quantity to get: 2.19 \xD7 10\u2076 times Z over n.","He\u207A (Z = 2) in n = 2: v = 2.19 \xD7 10\u2076 \xD7 2 \xF7 2 = 2.19 \xD7 10\u2076 m/s.","anorb"),e("Bohr model of hydrogen",1,"Energy of the nth level","E\u2099 = \u221213.6 {Z\xB2;n\xB2} eV \xB7 kinetic energy K = +13.6 {Z\xB2;n\xB2} eV \xB7 potential energy U = \u221227.2 {Z\xB2;n\xB2} eV \xB7 total E = \u2212K = {U;2} \xB7 E is negative, so the electron is bound; E = 0 at n = \u221E (free electron at rest) \xB7 E\u2099 in joule: \u22122.18 \xD7 10\u207B\xB9\u2078 Z\xB2/n\xB2","Learn the three ratios K : U : E = +1 : \u22122 : \u22121. An electron\u2019s energy rises (becomes less negative) as n increases.","Li\xB2\u207A in the ground state: E = \u221213.6 \xD7 9 = \u2212122.4 eV, K = 122.4 eV and U = \u2212244.8 eV.","anlev"),e("Bohr model of hydrogen",2,"Period, current and magnetic moment","T = {2\u03C0r;v} \u221D {n\xB3;Z\xB2} \xB7 f \u221D {Z\xB2;n\xB3} \xB7 I = ef \u221D {Z\xB2;n\xB3} \xB7 orbital magnetic moment \u03BC = IA = {e;2m}L = n{eh;4\u03C0m} \u221D n (Bohr magneton 9.27 \xD7 10\u207B\xB2\u2074 A m\xB2) \xB7 field at the nucleus B = {\u03BC\u2080I;2r} \u221D {Z\xB3;n\u2075}","Write each quantity in terms of r and v first, then substitute r \u221D n\xB2/Z and v \u221D Z/n. Take the ratio of two cases.","The time period in n = 2 against n = 1 in hydrogen is 2\xB3 : 1 = 8 : 1. In the ground state of hydrogen T = 2\u03C0 \xD7 0.529 \xD7 10\u207B\xB9\u2070 \xF7 2.19 \xD7 10\u2076 = 1.5 \xD7 10\u207B\xB9\u2076 s."),e("Bohr model of hydrogen",2,"De Broglie wave in a Bohr orbit","2\u03C0r\u2099 = n\u03BB \xB7 \u03BB = {h;mv} \xB7 this gives mvr = {nh;2\u03C0} \xB7 \u03BB\u2099 = {2\u03C0r\u2099;n} = 3.32 n \xC5 for hydrogen \xB7 the number of waves around the orbit is n","The idea of de Broglie explains why only certain orbits are allowed: a whole number of wavelengths must fit.","Hydrogen in n = 3: \u03BB = 3.32 \xD7 3 = 9.96 \xC5, and three wavelengths fit around the orbit of circumference 2\u03C0 \xD7 4.76 = 29.9 \xC5."),e("Hydrogen spectrum",1,"Rydberg formula","{1;\u03BB} = RZ\xB2({1;n\u2081\xB2} \u2212 {1;n\u2082\xB2}) with n\u2082 > n\u2081 \xB7 R = 1.097 \xD7 10\u2077 m\u207B\xB9 \xB7 {1;R} = 91.2 nm \xB7 Rhc = 13.6 eV \xB7 for hydrogen Z = 1 \xB7 energy of the photon E = 13.6 Z\xB2({1;n\u2081\xB2} \u2212 {1;n\u2082\xB2}) eV, and \u03BB(nm) = {1240;E in eV}","Put n\u2081 for the lower level (the series) and n\u2082 for the upper level. Do the bracket as a fraction before inverting.","H\u03B1 line (n\u2082 = 3 to n\u2081 = 2): 1/\u03BB = 1.097 \xD7 10\u2077 \xD7 5/36, so \u03BB = 656 nm (red).","anlev"),e("Hydrogen spectrum",1,"Series of hydrogen","Lyman: n\u2081 = 1, ultraviolet \xB7 Balmer: n\u2081 = 2, visible (and near ultraviolet) \xB7 Paschen: n\u2081 = 3, infrared \xB7 Brackett: n\u2081 = 4, infrared \xB7 Pfund: n\u2081 = 5, infrared \xB7 longest wavelength: n\u2082 = n\u2081 + 1 \xB7 shortest wavelength (series limit): n\u2082 = \u221E, \u03BB = {n\u2081\xB2;R} \xB7 Lyman 121.6 nm to 91.2 nm \xB7 Balmer 656.3 nm to 364.6 nm \xB7 Paschen 1875 nm to 820.6 nm","Learn which n\u2081 gives which series and the position in the spectrum. Only the Balmer series has visible lines in hydrogen.","Balmer: longest 656.3 nm, shortest 364.6 nm, ratio 9 : 5. Lyman longest \xF7 Balmer longest = (4/3) \xF7 (36/5) = 5 : 27.","anlev"),e("Hydrogen spectrum",1,"Number of spectral lines","electrons in many atoms jumping down from the level n to all lower levels: number of lines = {n(n \u2212 1);2} \xB7 for one atom the largest number of photons in one cascade from the level n is n \u2212 1 \xB7 from n = 2: 1 line, n = 3: 3, n = 4: 6, n = 5: 10, n = 6: 15 \xB7 lines in a particular series ending on n\u2081 from the level n: n \u2212 n\u2081","Count the pairs of levels. If the question asks for lines in the visible region or in one series, count only the jumps to the required lower level.","Gas excited to n = 5 gives 5 \xD7 4 \xF7 2 = 10 lines; of them 4 belong to the Lyman series."),e("Hydrogen spectrum",2,"Hydrogen-like ions and equal lines","for Z: {1;\u03BB} = Z\xB2R(\u2026) \xB7 E\u2099 \u221D Z\xB2 so every wavelength of the ion is 1/Z\xB2 times that of hydrogen for the same n\u2081 and n\u2082 \xB7 He\u207A lines with n\u2082 and n\u2081 both even (4 \u2192 2, 6 \u2192 4 \u2026) have the same wavelength as hydrogen lines \xB7 ratio of the wavelengths of the same transition in H and He\u207A is 4 : 1","Match Z\xB2(1/n\u2081\xB2 \u2212 1/n\u2082\xB2) of the ion with 1/n\u2081\u2032\xB2 \u2212 1/n\u2082\u2032\xB2 of hydrogen. Put n\u2081 = 2n\u2081\u2032, n\u2082 = 2n\u2082\u2032 for He\u207A.","He\u207A from n = 2 to n = 1: E = 13.6 \xD7 4 \xD7 3/4 = 40.8 eV, \u03BB = 1240 \xF7 40.8 = 30.4 nm, a quarter of 121.6 nm. He\u207A 4 \u2192 2 gives 10.2 eV, the same as hydrogen 2 \u2192 1."),e("Energy levels and transitions",1,"Excitation and ionisation energy","ionisation energy of the ground state: 13.6 Z\xB2 eV (hydrogen 13.6 eV, He\u207A 54.4 eV, Li\xB2\u207A 122.4 eV) \xB7 ionisation energy from the level n: {13.6Z\xB2;n\xB2} eV \xB7 first excitation energy (n = 1 to 2): 10.2 Z\xB2 eV \xB7 excitation potential 10.2 V, ionisation potential 13.6 V for hydrogen \xB7 binding energy of the electron in a level = \u2212E","Energy to reach a level = difference of the two energies. Ionisation is the transition to n = \u221E (E = 0).","Hydrogen in n = 2 needs 3.4 eV to ionise. He\u207A in n = 3 needs 54.4 \xF7 9 = 6.04 eV.","anlev"),e("Energy levels and transitions",1,"Absorption of a photon and collision with an electron","a photon is absorbed only if hf = Ef \u2212 Ei exactly (all of its energy is taken) \xB7 a photon with hf > 13.6 eV ionises the atom and the free electron has K = hf \u2212 13.6 eV \xB7 an electron of energy K can excite the atom if K \u2265 the gap and keeps the rest (K \u2212 gap) \xB7 gap n = 1 \u2192 2: 10.2 eV, \u2192 3: 12.09 eV, \u2192 4: 12.75 eV, \u2192 \u221E: 13.6 eV","A photon needs an exact match for a jump between levels, but any energy above 13.6 eV for ionisation. An electron can give any part of its energy that makes a jump allowed.","A 15 eV photon on ground-state hydrogen: ionisation, K = 15 \u2212 13.6 = 1.4 eV. An electron of 11 eV can raise the atom to n = 2 and leaves 0.8 eV, but cannot reach n = 3."),e("Energy levels and transitions",1,"Emission after excitation","after excitation to the level n the atom may emit every line between the levels up to n \xB7 the shortest wavelength is from n to 1 and the longest is from n to n \u2212 1 \xB7 the highest energy photon: 13.6 Z\xB2(1 \u2212 1/n\xB2) eV \xB7 the photon wavelength \u03BB = {1240;E} nm","Find the highest level that can be reached with the given energy, then count the lines and compute the wavelengths as asked.","Hydrogen bombarded with 12.5 eV electrons: 12.09 \u2264 12.5 < 12.75, so n = 3 is reached. Three lines come out: 3 \u2192 1 (102.6 nm), 2 \u2192 1 (121.6 nm), 3 \u2192 2 (656 nm).","anlev"),e("Energy levels and transitions",2,"Recoil of the atom","momentum is conserved: the photon momentum p = {E;c} is taken by the atom in the opposite direction \xB7 recoil speed v = {E;mc} \xB7 recoil energy {p\xB2;2m} = {E\xB2;2mc\xB2}, which is far smaller than E (about 10\u207B\u2078 of E) \xB7 the photon energy is therefore slightly less than the energy difference of the levels","Calculate the momentum of the photon and divide it by the mass of the atom. The recoil is negligible in questions on energy.","Hydrogen emitting a 10.2 eV photon: p = 10.2 \xD7 1.6 \xD7 10\u207B\xB9\u2079 \xF7 3 \xD7 10\u2078 = 5.4 \xD7 10\u207B\xB2\u2077 kg m/s, v = 5.4 \xD7 10\u207B\xB2\u2077 \xF7 1.67 \xD7 10\u207B\xB2\u2077 = 3.3 m/s."),e("Nucleus: composition and size",1,"Composition and kinds of nuclei","\u1D2C_ZX: Z = atomic number (protons), A = mass number (nucleons), N = A \u2212 Z neutrons \xB7 isotopes: same Z, different A (\xB9H, \xB2H, \xB3H) \xB7 isobars: same A, different Z (\xB3H and \xB3He) \xB7 isotones: same N \xB7 isomers: same A and Z in different energy states \xB7 the isotopes have the same chemical properties and different mass","Read the symbol in this way: top left is A, bottom left is Z. Neutrons = A \u2212 Z.","\xB2\xB3\u2078\u2089\u2082U has 92 protons and 238 \u2212 92 = 146 neutrons. \xB2\xB3\u2075U is an isotope of it; \xB9\u2074C and \xB9\u2074N are isobars."),e("Nucleus: composition and size",1,"Nuclear radius","R = R\u2080A^(1/3) with R\u2080 = 1.2 fm (1 fm = 10\u207B\xB9\u2075 m) \xB7 R \u221D A^(1/3) \xB7 volume \u221D A \xB7 {R\u2081;R\u2082} = ({A\u2081;A\u2082})^(1/3) \xB7 a nucleus of A = 8 has twice the radius of A = 1","Take the cube root of A. For ratios write only R \u221D A^(1/3); doubling the radius means eight times the nucleons.","A = 64: R = 1.2 \xD7 4 = 4.8 fm. A = 27 and A = 64 have radii in the ratio 3 : 4."),e("Nucleus: composition and size",1,"Nuclear density","\u03C1 = {mass;volume} = {A \xD7 1.66 \xD7 10\u207B\xB2\u2077;(4/3)\u03C0(R\u2080A^(1/3))\xB3} = 2.3 \xD7 10\xB9\u2077 kg/m\xB3 \xB7 independent of A (same for all nuclei) \xB7 about 10\xB9\u2074 times the density of water \xB7 the density does not depend on the size, so the nucleons are packed in the same way in every nucleus \xB7 number density of nucleons about 1.4 \xD7 10\u2074\u2074 per m\xB3","Cancel A: the ratio of the densities of two nuclei is 1. The charge density, however, depends on Z/A.","One cubic centimetre of nuclear matter: 2.3 \xD7 10\xB9\u2077 \xD7 10\u207B\u2076 = 2.3 \xD7 10\xB9\xB9 kg, 230 million tonnes."),e("Nucleus: composition and size",1,"Atomic mass unit and mass-energy","1 u = {1;12} of the mass of \xB9\xB2C atom = 1.66 \xD7 10\u207B\xB2\u2077 kg = 931.5 MeV/c\xB2 \xB7 E = mc\xB2 \xB7 mass of proton 1.00728 u, neutron 1.00866 u, electron 0.00055 u (0.511 MeV/c\xB2) \xB7 1 eV = 1.6 \xD7 10\u207B\xB9\u2079 J","The energy equivalent of a mass in u is mass \xD7 931.5 MeV. For a mass in kg use c\xB2 = 9 \xD7 10\xB9\u2076 m\xB2/s\xB2.","1 mg converted completely gives 10\u207B\u2076 \xD7 9 \xD7 10\xB9\u2076 = 9 \xD7 10\xB9\u2070 J."),e("Nucleus: composition and size",1,"Nuclear force","strong, attractive and acts over a short range of a few femtometre \xB7 about the same between p\u2013p, n\u2013n and p\u2013n (charge independent) \xB7 saturated: a nucleon feels only its neighbours \xB7 not a central force and depends on spin \xB7 much stronger than the Coulomb force at 1 fm, but decays quickly beyond a few fm \xB7 in heavy nuclei the Coulomb repulsion of the protons grows as Z\xB2, so N/Z rises from 1 (light) to about 1.5 (heavy)","To compare forces choose the distance: gravitational \u226A electromagnetic \u226A nuclear at 1 fm. Use short range and saturation to explain why BE per nucleon becomes constant.","\xB2\u2070\u2078Pb has N/Z = 126 \xF7 82 = 1.54, while \xB9\xB2C has N/Z = 1."),e("Mass defect and binding energy",1,"Mass defect and binding energy","\u0394m = Zm\u209A + (A \u2212 Z)m\u2099 \u2212 M(nucleus) \xB7 using atomic masses: \u0394m = Z m(\xB9H) + (A \u2212 Z)m\u2099 \u2212 M(atom), because the electron masses cancel \xB7 BE = \u0394m \xD7 931.5 MeV (\u0394m in u) \xB7 BE is the energy needed to separate the nucleus completely into its free nucleons \xB7 the mass of a nucleus is less than the sum of its nucleons","Use the mass of the hydrogen atom for the protons if the mass of the atom is given. Do not use the electron mass again.","\u2074He: \u0394m = 2 \xD7 1.007825 + 2 \xD7 1.008665 \u2212 4.002603 = 0.030377 u, so BE = 0.030377 \xD7 931.5 = 28.3 MeV.","anbe"),e("Mass defect and binding energy",1,"Binding energy per nucleon","BE/A = {BE;A} \xB7 higher BE/A means a more stable nucleus \xB7 \u2074He 7.07 MeV, \xB9\xB2C 7.68 MeV, \u2075\u2076Fe 8.8 MeV (near the greatest), \xB2\xB3\u2078U 7.6 MeV \xB7 most nuclei in the middle (A = 30 to 170) have BE/A about 8 MeV \xB7 \xB2H has only 1.11 MeV","Compare nuclei with BE/A, not with the total BE. A heavier nucleus has the larger BE and may be less stable.","\xB2H: BE = 2.22 MeV, so BE/A = 1.11 MeV. \u2074He: 28.3 \xF7 4 = 7.07 MeV.","anbe"),e("Mass defect and binding energy",1,"Binding energy curve","BE/A rises steeply for A < 20 (peaks at \u2074He, \xB9\xB2C, \xB9\u2076O), has a broad maximum of about 8.8 MeV near A = 56 and decreases slowly to 7.6 MeV at A = 238 \xB7 fusion of light nuclei (A < 56) and fission of heavy nuclei (A > 56) both move towards the peak and release energy \xB7 nuclei near A = 56 are the most stable \xB7 the curve is nearly flat from A = 30 to 170, which shows that the nuclear force is saturated","Energy is released whenever a process raises the BE per nucleon. State the direction: A below 56, fusion; A above 56, fission.","Fission of A = 240 (BE/A = 7.6 MeV) into two nuclei of A = 120 (8.5 MeV): the gain is 240 \xD7 0.9 = 216 MeV.","anbe"),e("Mass defect and binding energy",1,"Q value of a reaction","Q = (\u03A3 mass of reactants \u2212 \u03A3 mass of products)c\xB2 \xB7 Q = \u03A3(BE of products) \u2212 \u03A3(BE of reactants) \xB7 Q > 0: energy is released (exothermic) \xB7 Q < 0: energy must be supplied (endothermic) \xB7 Q is shared as kinetic energy of the products","With the BE use the total BE of each side (BE per nucleon times A). With masses subtract the sum of the products from the reactants.","\xB2H + \xB3H \u2192 \u2074He + n: BE of the products = 28.3 MeV, of the reactants 2.22 + 8.48 = 10.70 MeV, so Q = 17.6 MeV.","anbe"),e("Mass defect and binding energy",2,"Separation energy of a nucleon","energy to remove one neutron: S\u2099 = BE(A, Z) \u2212 BE(A \u2212 1, Z) \xB7 it is larger for a nucleus with a closed shell and an even number of nucleons \xB7 for \u2074He the removal of one neutron costs far more than the average of 7.07 MeV","Take the difference between the binding energy of the nucleus and that of the nucleus left behind.","BE of \xB3He is 7.72 MeV and of \u2074He 28.30 MeV: removing a neutron from \u2074He needs 28.30 \u2212 7.72 = 20.6 MeV."),e("Fission and fusion",1,"Nuclear fission","a heavy nucleus splits into two medium fragments with two or three neutrons after it absorbs a slow neutron \xB7 \xB2\xB3\u2075U + n \u2192 \xB9\u2074\xB9Ba + \u2079\xB2Kr + 3n + about 200 MeV (A: 236 \u2192 141 + 92 + 3; Z: 92 \u2192 56 + 36) \xB7 energy per fission about 200 MeV, about 0.85 MeV per nucleon \xB7 most of it appears as kinetic energy of the fragments \xB7 fission fragments are neutron-rich and radioactive","Check A and Z on both sides. For the energy from a mass of fuel, find the number of nuclei (m \xF7 M \xD7 6.02 \xD7 10\xB2\xB3) and multiply by 200 MeV.","1 kg of \xB2\xB3\u2075U fissioned completely: N = 1000 \xF7 235 \xD7 6.02 \xD7 10\xB2\xB3 = 2.56 \xD7 10\xB2\u2074, E = 2.56 \xD7 10\xB2\u2074 \xD7 200 \xD7 1.6 \xD7 10\u207B\xB9\xB3 = 8.2 \xD7 10\xB9\xB3 J, about 20 000 tonnes of TNT.","anbe"),e("Fission and fusion",1,"Chain reaction and the reactor","each fission frees 2 or 3 neutrons, which cause more fission \xB7 multiplication factor k = {neutrons in a generation;neutrons in the previous generation} \xB7 k < 1: the reaction dies out; k = 1: steady (a reactor); k > 1: it grows (a bomb) \xB7 moderator (heavy water, graphite) slows neutrons to thermal energies \xB7 control rods (cadmium, boron) absorb neutrons \xB7 coolant carries the heat away \xB7 a critical mass is needed","Match the parts with their function. For the growth after n generations use k\u207F.","With k = 1.05 the number of neutrons after 100 generations is 1.05\xB9\u2070\u2070 = 131 times larger."),e("Fission and fusion",1,"Nuclear fusion","light nuclei join to form a heavier one with larger BE/A \xB7 \xB2H + \xB2H \u2192 \xB3He + n + 3.27 MeV \xB7 \xB2H + \xB3H \u2192 \u2074He + n + 17.6 MeV \xB7 in the Sun four \xB9H become one \u2074He with the release of about 26.7 MeV \xB7 it needs a temperature of 10\u2077 K to 10\u2078 K so that the nuclei overcome the Coulomb repulsion (thermonuclear reaction) \xB7 energy per nucleon is about four times that of fission","Remember the energy of one reaction, then divide by the number of nucleons to compare with fission.","\xB2H + \xB3H: 17.6 \xF7 5 = 3.5 MeV per nucleon, against 0.85 MeV per nucleon in the fission of \xB2\xB3\u2075U."),e("Fission and fusion",2,"Power from fission and the Sun","power P = (number of fissions per second) \xD7 200 MeV \xB7 fissions per second = {P;200 MeV in joule} \xB7 the Sun radiates 3.8 \xD7 10\xB2\u2076 W, so the mass it loses is {P;c\xB2} = 4 \xD7 10\u2079 kg every second \xB7 a reactor that is 30 % efficient needs three times as many fissions for the same electric power","Convert MeV into joule (\xD7 1.6 \xD7 10\u207B\xB9\xB3) and divide the power by this energy.","A reactor of thermal power 1000 MW needs 10\u2079 \xF7 (200 \xD7 1.6 \xD7 10\u207B\xB9\xB3) = 3.1 \xD7 10\xB9\u2079 fissions every second."),e("Radioactivity and decay law",1,"Law of radioactive decay","the number of nuclei decaying per second is proportional to the number present: {dN;dt} = \u2212\u03BBN \xB7 N = N\u2080e^(\u2212\u03BBt) \xB7 \u03BB = decay constant (probability of decay per unit time, s\u207B\xB9) \xB7 decay is random and spontaneous, independent of temperature, pressure and chemical state \xB7 the mass also decays as m = m\u2080e^(\u2212\u03BBt)","Use the exponential form when t is not a whole number of half-lives. In a graph of ln N against t, the slope is \u2212\u03BB.","\u03BB = 0.01 s\u207B\xB9 and t = 100 s: N \xF7 N\u2080 = e\u207B\xB9 = 0.37.","andec"),e("Radioactivity and decay law",1,"Half-life and mean life","T = {0.693;\u03BB} = {ln 2;\u03BB} \xB7 \u03C4 = {1;\u03BB} = 1.44 T \xB7 N = N\u2080(1/2)^(t/T) \xB7 after n half-lives N = N\u2080/2\u207F \xB7 at t = \u03C4, N = N\u2080/e = 0.37 N\u2080 \xB7 the sum of the lives of all nuclei divided by N\u2080 gives \u03C4 \xB7 63 % has decayed at t = \u03C4 and 50 % at t = T","Use the powers of 1/2 when the time is a multiple of T. For other times write t/T as a decimal.","T = 10 min, t = 25 min: N \xF7 N\u2080 = (1/2)^2.5 = 0.177, 17.7 % is left.","andec"),e("Radioactivity and decay law",1,"Activity","A = \u2212{dN;dt} = \u03BBN = A\u2080e^(\u2212\u03BBt) \xB7 A = A\u2080/2^(t/T) \xB7 unit becquerel (Bq) = 1 decay per second \xB7 1 curie (Ci) = 3.7 \xD7 10\xB9\u2070 Bq \xB7 1 rutherford = 10\u2076 Bq \xB7 activity is proportional to the number of nuclei, so it falls with the same half-life \xB7 the activity of a given amount is larger for a smaller T","Find \u03BB in s\u207B\xB9 from T, then A = \u03BBN. A sample with equal N and smaller T has more activity.","N = 10\xB2\u2070 nuclei, T = 1 hour: \u03BB = 0.693 \xF7 3600 = 1.93 \xD7 10\u207B\u2074 s\u207B\xB9, A = 1.93 \xD7 10\xB9\u2076 Bq = 5.2 \xD7 10\u2075 Ci.","andec"),e("Radioactivity and decay law",1,"Fraction decayed and mass left","fraction decayed = 1 \u2212 e^(\u2212\u03BBt) = 1 \u2212 2^(\u2212t/T) \xB7 after 1, 2, 3, 4 half-lives: \xBD, \xBE, \u215E, 15/16 decayed \xB7 time to fall to a fraction f: t = T log\u2082(1/f) = {1;\u03BB} ln(N\u2080/N) \xB7 mass left m = m\u2080/2^(t/T) \xB7 the number decayed in a time is N(t\u2081) \u2212 N(t\u2082)","Find the number of half-lives n = t/T first. For the decayed amount subtract the remaining amount from the starting amount.","T = 5 days, 20 g, 15 days: n = 3, m = 20 \xF7 8 = 2.5 g left and 17.5 g decayed. 90 % decayed needs t = T log\u208210 = 3.32 T."),e("Radioactivity and decay law",1,"Alpha, beta and gamma","\u03B1: helium nucleus \u2074\u2082He, A falls by 4, Z falls by 2; discrete energies of 4 MeV to 9 MeV; most ionising, least penetrating (stopped by paper), speed about 10\u2077 m/s \xB7 \u03B2\u207B: n \u2192 p + e\u207B + \u03BD\u0304, Z rises by 1, A same; continuous energy spectrum (the neutrino shares the energy); penetrates a few mm of aluminium \xB7 \u03B2\u207A: p \u2192 n + e\u207A + \u03BD, Z falls by 1 \xB7 \u03B3: photon from an excited nucleus, A and Z same; no charge; most penetrating (cm of lead); speed c \xB7 in an electric or magnetic field \u03B1 and \u03B2 bend in opposite ways, \u03B3 does not bend","A decay equation must balance A and Z. The electron in \u03B2\u207B decay is created in the nucleus; it was not in it before.","\xB2\xB3\u2078\u2089\u2082U \u2192 \xB2\xB3\u2074\u2089\u2080Th + \u2074\u2082He. \xB9\u2074\u2086C \u2192 \xB9\u2074\u2087N + e\u207B + \u03BD\u0304."),e("Radioactivity and decay law",1,"Number of \u03B1 and \u03B2 particles in a series","n\u03B1 = {A \u2212 A\u2032;4} \xB7 n\u03B2 (\u03B2\u207B) = Z\u2032 \u2212 Z + 2n\u03B1 \xB7 each \u03B1 lowers A by 4 and Z by 2; each \u03B2\u207B raises Z by 1 \xB7 the daughter of an \u03B1 decay lies two places to the left in the periodic table","First find n\u03B1 from the fall in A, then find n\u03B2 from the net change of Z.","\xB2\xB3\u2078U \u2192 \xB2\u2070\u2076Pb: n\u03B1 = (238 \u2212 206) \xF7 4 = 8; Z: 92 \u2212 16 + n\u03B2 = 82, so n\u03B2 = 6."),e("Radioactivity and decay law",1,"Energy shared in \u03B1 decay","Q = (M parent \u2212 M daughter \u2212 M \u03B1)c\xB2 \xB7 momentum conservation: the daughter and the \u03B1 particle have equal and opposite momentum \xB7 K\u03B1 = Q{A \u2212 4;A} \xB7 Kd = Q{4;A} \xB7 the \u03B1 particle carries almost all of Q","Use p\xB2 = 2mK for both and the ratio of masses 4 : (A \u2212 4).","\xB2\xB2\u2076Ra \u2192 \xB2\xB2\xB2Rn + \u03B1 with Q = 4.87 MeV: K\u03B1 = 4.87 \xD7 222 \xF7 226 = 4.78 MeV."),e("Radioactivity and decay law",2,"Successive decay","parent \u2192 daughter \u2192 \u2026: {dN\u2082;dt} = \u03BB\u2081N\u2081 \u2212 \u03BB\u2082N\u2082 \xB7 secular equilibrium (T\u2081 \u226B T\u2082): \u03BB\u2081N\u2081 = \u03BB\u2082N\u2082, that is the activities are equal and {N\u2081;N\u2082} = {\u03BB\u2082;\u03BB\u2081} = {T\u2081;T\u2082} \xB7 the daughter activity first rises and then follows the parent","At equilibrium equate the two activities and use N \u221D T.","\xB2\xB2\u2076Ra (T = 1600 y) and \xB2\xB2\xB2Rn (T = 3.8 d) in equilibrium: N(Ra) \xF7 N(Rn) = 1600 \xD7 365 \xF7 3.8 = 1.5 \xD7 10\u2075."),e("Radioactivity and decay law",2,"Parallel decay","a nucleus can decay by two routes: \u03BB = \u03BB\u2081 + \u03BB\u2082 \xB7 {1;T} = {1;T\u2081} + {1;T\u2082}, so T = {T\u2081T\u2082;T\u2081 + T\u2082} \xB7 the fraction by the route 1 is {\u03BB\u2081;\u03BB} = {T\u2082;T\u2081 + T\u2082} \xB7 the half-life of the sample is shorter than either T\u2081 or T\u2082","Add the decay constants, not the half-lives.","T\u2081 = 20 min and T\u2082 = 30 min: T = 20 \xD7 30 \xF7 50 = 12 min and 30 \xF7 50 = 60 % decay by route 1."),e("Radioactivity and decay law",2,"Radiocarbon dating","living matter has a constant ratio of \xB9\u2074C to \xB9\xB2C because of the exchange with the air; after death the \xB9\u2074C decays with T = 5730 years \xB7 age t = {T;0.693} ln{A\u2080;A} = {T;0.693} ln{N\u2080;N} \xB7 the method is useful for ages of a few thousand to about 50 000 years","Compare the activity of the sample with that of a living sample of the same mass.","If the activity of a bone is one fourth of that of living matter, two half-lives have passed: 2 \xD7 5730 = 11 460 years.")],look:["Rutherford: nucleus 10\u207B\xB9\u2075 m, atom 10\u207B\xB9\u2070 m; r\u2080 = 2Ze\xB2/(4\u03C0\u03B5\u2080K) = 2Z \xD7 1.44/K(MeV) fm; b = (r\u2080/2) cot(\u03B8/2); N \u221D 1/sin\u2074(\u03B8/2)","Bohr: mvr = nh/2\u03C0; r = 0.529 n\xB2/Z \xC5; v = 2.19 \xD7 10\u2076 Z/n m/s; E = \u221213.6 Z\xB2/n\xB2 eV; K : U : E = 1 : \u22122 : \u22121","T \u221D n\xB3/Z\xB2, I \u221D Z\xB2/n\xB3, \u03BC \u221D n, 2\u03C0r = n\u03BB (\u03BB = 3.32 n \xC5 in hydrogen)","1/\u03BB = RZ\xB2(1/n\u2081\xB2 \u2212 1/n\u2082\xB2), R = 1.097 \xD7 10\u2077 m\u207B\xB9, 1/R = 91.2 nm, \u03BB(nm) = 1240/E(eV)","Series: Lyman n\u2081 = 1 (UV), Balmer 2 (visible), Paschen 3, Brackett 4, Pfund 5 (all IR); lines from level n: n(n \u2212 1)/2","Ionisation 13.6 Z\xB2 eV; first excitation 10.2 Z\xB2 eV; a photon needs an exact match, an electron can give part; h\u03BD > 13.6 leaves K = h\u03BD \u2212 13.6","A = Z + N; R = 1.2 A^(1/3) fm; density 2.3 \xD7 10\xB9\u2077 kg/m\xB3 independent of A; 1 u = 931.5 MeV; nuclear force strong, short range, charge independent","\u0394m = Zm\u209A + (A \u2212 Z)m\u2099 \u2212 M; BE = \u0394m \xD7 931.5 MeV; curve peaks near A = 56 (8.8 MeV); Q = \u03A3BE(products) \u2212 \u03A3BE(reactants)","Fission \u2248 200 MeV (k < 1, = 1, > 1; moderator, control rods); fusion needs 10\u2077 K, d + t gives 17.6 MeV","N = N\u2080e^(\u2212\u03BBt) = N\u2080/2^(t/T); T = 0.693/\u03BB; \u03C4 = 1.44 T; A = \u03BBN; 1 Ci = 3.7 \xD7 10\xB9\u2070 Bq; n\u03B1 = \u0394A/4; K\u03B1 = Q(A \u2212 4)/A; parallel \u03BB = \u03BB\u2081 + \u03BB\u2082"],notes:[{h:"Rutherford model and alpha scattering",items:["In the experiment \u03B1 particles from a radioactive source hit a thin gold foil and were counted on a screen.","Most went straight, some were deflected, and about 1 in 8000 came back.","The conclusion: all the positive charge and almost all of the mass are in a tiny nucleus.","The distance of closest approach is found by changing all the kinetic energy into potential energy.","A small impact parameter gives a large angle; b = 0 gives 180\xB0.","The model cannot explain the stability of the atom or its line spectrum, and this led to Bohr\u2019s model."],fig:"anscat"},{h:"Bohr model of hydrogen",items:["Bohr kept the orbits of Rutherford and added quantum rules.","Angular momentum mvr is a whole number times h/2\u03C0.","The electron does not radiate in a stationary orbit; radiation comes out only in a jump.","The radius grows as n\xB2, the speed falls as 1/n and the energy rises as \u22121/n\xB2.","The ratio kinetic : potential : total energy is 1 : \u22122 : \u22121.","The theory works for H, He\u207A, Li\xB2\u207A and fails for atoms with more than one electron."],fig:"anorb"},{h:"Quantities in the nth orbit",items:["r\u2099 = 0.529 n\xB2/Z \xC5 and v\u2099 = 2.19 \xD7 10\u2076 Z/n m/s.","The period T \u221D n\xB3/Z\xB2, so the frequency and the current go as Z\xB2/n\xB3.","The orbital magnetic moment \u03BC is proportional to n.","The field at the nucleus goes as Z\xB3/n\u2075.","The de Broglie wavelength \u03BB = h/mv fits n times around the orbit.","For ratios between two orbits or two ions, write each quantity in terms of n and Z only."]},{h:"Hydrogen spectrum",items:["The Rydberg formula gives every line in the spectrum of hydrogen.","Lyman lines are in the ultraviolet, Balmer in the visible region, the rest in the infrared.","The longest line of a series has n\u2082 = n\u2081 + 1; the series limit has n\u2082 = \u221E.","The shortest wavelength of the Lyman series is 91.2 nm.","The lines of a series come closer together as n\u2082 increases.","From the level n an atom can give n(n \u2212 1)/2 different lines."],fig:"anlev"},{h:"Energy levels and excitation",items:["The levels are E\u2099 = \u221213.6/n\xB2 eV and they crowd together near zero.","The ionisation energy of hydrogen is 13.6 eV and the first excitation energy is 10.2 eV.","A photon is absorbed only if its energy equals the gap between two levels.","A photon of more than 13.6 eV ionises the atom; the surplus is the kinetic energy of the electron.","An electron can excite the atom with a part of its energy if it is more than the gap.","For hydrogen-like ions all energies are multiplied by Z\xB2."],fig:"anlev"},{h:"Composition and size of the nucleus",items:["The nucleus has Z protons and N = A \u2212 Z neutrons, together called nucleons.","Isotopes have the same Z; isobars have the same A; isotones have the same N.","R = 1.2 A^(1/3) fm, so the volume is proportional to A.","The density is 2.3 \xD7 10\xB9\u2077 kg/m\xB3 for every nucleus.","1 u = 931.5 MeV/c\xB2 = 1.66 \xD7 10\u207B\xB2\u2077 kg.","The nuclear force is strong, short ranged, charge independent and saturated."]},{h:"Mass defect and binding energy",items:["The mass of a nucleus is less than the total mass of its separate nucleons.","The difference \u0394m is the mass defect; BE = \u0394m \xD7 931.5 MeV.","BE per nucleon is a measure of the stability of the nucleus.","The curve peaks near iron (A = 56) at about 8.8 MeV.","Light nuclei (A < 56) can gain by fusion and heavy nuclei (A > 56) by fission.","\u2074He is a very stable light nucleus, with a high peak in the curve."],fig:"anbe"},{h:"Fission and fusion",items:["In fission a heavy nucleus splits and releases about 200 MeV with two or three neutrons.","The neutrons cause a chain reaction; k = 1 in a reactor.","A moderator slows the neutrons and control rods absorb them.","In fusion light nuclei join; this needs very high temperature (10\u2077 K or more).","The Sun and stars get their energy from fusion.","Energy per unit mass is greater in fusion; fission is used in power plants."]},{h:"Radioactive decay law",items:["Decay is random: each nucleus has the same chance \u03BB per second.","N = N\u2080e^(\u2212\u03BBt) and the activity A = \u03BBN falls in the same way.","The half-life is T = 0.693/\u03BB and the mean life is \u03C4 = 1/\u03BB = 1.44 T.","After n half-lives a fraction 1/2\u207F is left.","The activity is measured in becquerel; 1 Ci = 3.7 \xD7 10\xB9\u2070 Bq.","Temperature, pressure and chemical form do not change \u03BB."],fig:"andec"},{h:"Alpha, beta, gamma and decay series",items:["An \u03B1 particle is a helium nucleus; it lowers A by 4 and Z by 2.","In \u03B2\u207B decay a neutron becomes a proton and Z rises by 1; the neutrino shares the energy.","Gamma rays are photons from an excited nucleus; A and Z do not change.","Ionising power: \u03B1 > \u03B2 > \u03B3. Penetrating power: \u03B3 > \u03B2 > \u03B1.","The number of \u03B1 particles is the fall of A divided by 4; the \u03B2 count follows from Z.","Parallel decay adds the decay constants; in successive decay a daughter reaches equilibrium with a long-lived parent."]}],asked:[{t:"Rutherford\u2019s experiment and its conclusions",what:"Statements about the \u03B1 scattering experiment are given. Choose the correct inference about the nucleus and the atom.",steps:["Most \u03B1 pass straight: the atom is mostly empty.","Few large deflections: a small, heavy, positive nucleus.","Size: nucleus 10\u207B\xB9\u2075 m, atom 10\u207B\xB9\u2070 m."],ex:"About 1 in 8000 returns: a nucleus of charge Ze and of size 10\u207B\xB9\u2075 m.",tp:"ruth",fig:"anscat"},{t:"Distance of closest approach",what:"The kinetic energy of an \u03B1 particle (or a proton) and the atomic number of the target are given. Find the distance of closest approach, or the energy for a given distance.",steps:["K = k q\u2081q\u2082/r\u2080.","r\u2080 = 2Z \xD7 1.44 \xF7 K(MeV) fm for an \u03B1 particle.","Doubling v makes r\u2080 one fourth."],ex:"5 MeV \u03B1 on gold: 45.5 fm.",tp:"ruth",fig:"anscat"},{t:"Impact parameter and angle of scattering",what:"The impact parameter and the energy are given. Find the angle, or find b for 90\xB0 or 180\xB0.",steps:["Find r\u2080 first.","b = (r\u2080/2) cot(\u03B8/2).","b = 0 gives 180\xB0."],ex:"5 MeV \u03B1 on gold, \u03B8 = 90\xB0: b = 22.8 fm.",tp:"ruth"},{t:"Radius, speed and energy of an electron in Bohr\u2019s orbit",what:"The level n and the atom (H, He\u207A, Li\xB2\u207A) are given. Find the radius, the speed, the kinetic or total energy, or compare two cases.",steps:["r = 0.529 n\xB2/Z \xC5.","v = 2.19 \xD7 10\u2076 Z/n m/s.","E = \u221213.6 Z\xB2/n\xB2 eV; K = \u2212E."],ex:"Li\xB2\u207A, n = 2: r = 0.705 \xC5. He\u207A, n = 2: v = 2.19 \xD7 10\u2076 m/s.",tp:"bohr",fig:"anorb"},{t:"Period, current and magnetic moment in the nth orbit",what:"The time period, the equivalent current, the magnetic moment or the angular momentum is asked for two orbits or two ions as a ratio.",steps:["T \u221D n\xB3/Z\xB2, I \u221D Z\xB2/n\xB3.","\u03BC = n eh/4\u03C0m, L = nh/2\u03C0.","Put r\u2099 \u221D n\xB2/Z and v\u2099 \u221D Z/n."],ex:"Hydrogen n = 2 against n = 1: T is 8 times.",tp:"bohr"},{t:"Wavelength of a line from the Rydberg formula",what:"Two levels of hydrogen (or of an ion) are given. Find the wavelength or the frequency of the emitted line.",steps:["1/\u03BB = RZ\xB2(1/n\u2081\xB2 \u2212 1/n\u2082\xB2).","R = 1.097 \xD7 10\u2077 m\u207B\xB9.","Or E = 13.6 Z\xB2(\u2026) and \u03BB = 1240/E nm."],ex:"3 \u2192 2 in hydrogen: 656 nm.",tp:"spec",fig:"anlev"},{t:"Longest and shortest wavelength of a series",what:"A series (Lyman, Balmer, Paschen) is named. Find the longest wavelength, the shortest one, or the ratio.",steps:["Longest: n\u2082 = n\u2081 + 1.","Shortest: n\u2082 = \u221E, \u03BB = n\u2081\xB2/R.","Balmer 656.3 nm to 364.6 nm."],ex:"Balmer: longest \xF7 shortest = 9 : 5.",tp:"spec",fig:"anlev"},{t:"Number of spectral lines",what:"The atoms are excited to the level n. Find the number of different lines, or the lines in the visible or in one series.",steps:["n(n \u2212 1)/2 for all jumps.","n \u2212 n\u2081 for the lines ending on n\u2081.","Visible lines are those that end on n = 2."],ex:"n = 5: 10 lines in all.",tp:"spec"},{t:"Ionisation and excitation energy",what:"The atom or ion and its state are given. Find the energy to excite it to a given level or to remove the electron, or the potential in volt.",steps:["Ionisation from n: 13.6 Z\xB2/n\xB2 eV.","Excitation = Ef \u2212 Ei.","Potential in volt = energy in eV."],ex:"He\u207A ground state: 54.4 eV; hydrogen n = 2: 3.4 eV.",tp:"energy"},{t:"Photon absorbed or emitted in a transition",what:"A photon is absorbed or emitted in a jump. Find its energy, its wavelength, or the final level.",steps:["hf = |Ef \u2212 Ei|.","\u03BB(nm) = 1240/E(eV).","For absorption, the photon must have exactly the gap energy."],ex:"4 \u2192 2 in hydrogen: 2.55 eV, 486 nm.",tp:"energy",fig:"anlev"},{t:"Excitation by collision with an electron or a photon",what:"A beam of electrons or photons of given energy hits hydrogen. Find the levels reached, the lines seen, or the energy left.",steps:["List the gaps: 10.2, 12.09, 12.75, 13.6 eV.","The highest gap not above the energy is the level reached.","Ionisation by a photon leaves K = hf \u2212 13.6."],ex:"12.5 eV electrons: n = 3, three lines.",tp:"energy"},{t:"Hydrogen-like ion with a line equal to that of hydrogen",what:"A transition in He\u207A or Li\xB2\u207A is to be matched with a transition in hydrogen, or the wavelength in the ion is asked.",steps:["Z\xB2(1/n\u2081\xB2 \u2212 1/n\u2082\xB2) for the ion.","Equate it with 1/n\u2081\u2032\xB2 \u2212 1/n\u2082\u2032\xB2 for hydrogen.","He\u207A: even levels double those of hydrogen."],ex:"He\u207A 4 \u2192 2 has the same wavelength (121.6 nm) as H 2 \u2192 1.",tp:"energy"},{t:"Isotopes, isobars and composition of the nucleus",what:"A symbol or a decay is given. Find the number of protons, neutrons and nucleons, or name isotopes, isobars and isotones.",steps:["Z = protons, N = A \u2212 Z.","Same Z: isotopes. Same A: isobars.","Same N: isotones."],ex:"\xB2\xB3\u2078U: 92 protons, 146 neutrons.",tp:"comp"},{t:"Nuclear radius, volume and density",what:"The mass number is given. Find the radius, or the ratio of radii, volumes and densities of two nuclei.",steps:["R = 1.2 A^(1/3) fm.","V \u221D A, so \u03C1 is the same.","\u03C1 = 2.3 \xD7 10\xB9\u2077 kg/m\xB3."],ex:"A = 64: 4.8 fm. A = 27 and 64: radii 3 : 4.",tp:"comp"},{t:"Binding energy from masses",what:"The masses of a nucleus (or atom) and of the nucleons are given. Find the mass defect, the binding energy and the binding energy per nucleon.",steps:["\u0394m = Zm\u209A + (A \u2212 Z)m\u2099 \u2212 M.","BE = 931.5 \u0394m MeV.","Divide by A for BE per nucleon."],ex:"\u2074He: \u0394m = 0.030377 u, BE = 28.3 MeV, 7.07 MeV per nucleon.",tp:"be"},{t:"Binding energy curve",what:"Statements about the curve of BE per nucleon against A are given. Say which nuclei are stable, where fission or fusion releases energy, and read the energy released.",steps:["The peak is at A = 56 (8.8 MeV).","Moving towards the peak releases energy.","Energy = A \xD7 (change of BE/A)."],ex:"A = 240 (7.6) into two of A = 120 (8.5): 216 MeV.",tp:"be",fig:"anbe"},{t:"Q value and energy released in a nuclear reaction",what:"The masses or the binding energies of the reactants and the products are given. Find Q or the energy released, and the kinetic energy shared.",steps:["Q = (\u03A3m reactants \u2212 \u03A3m products)c\xB2.","Or \u03A3 BE of products \u2212 \u03A3 BE of reactants.","Q > 0 means energy is released."],ex:"\xB2H + \xB3H \u2192 \u2074He + n: 17.6 MeV.",tp:"fiss",fig:"anbe"},{t:"Fission, chain reaction and power of a reactor",what:"The energy per fission and the fuel or the power is given. Find the energy from a mass, the rate of fission, or the multiplication factor.",steps:["N = (m/M) \xD7 6.02 \xD7 10\xB2\xB3.","Energy = N \xD7 200 MeV.","k < 1, = 1, > 1."],ex:"1 kg of \xB2\xB3\u2075U: 8.2 \xD7 10\xB9\xB3 J.",tp:"fiss"},{t:"Fraction left, half-life and mean life",what:"The half-life and a time are given. Find the fraction left, the time for a given fraction, or the mean life.",steps:["N = N\u2080/2^(t/T).","T = 0.693/\u03BB, \u03C4 = 1.44 T.","The time for a fraction f: t = T log\u2082(1/f)."],ex:"T = 10 min, t = 25 min: 17.7 % is left.",tp:"decay",fig:"andec"},{t:"Activity and the number of nuclei",what:"The activity, the number of nuclei or the mass is given. Find the activity, the decay constant or the activity after some time.",steps:["A = \u03BBN.","A = A\u2080/2^(t/T).","1 Ci = 3.7 \xD7 10\xB9\u2070 Bq."],ex:"10\xB2\u2070 nuclei, T = 1 h: 1.9 \xD7 10\xB9\u2076 Bq.",tp:"decay",fig:"andec"},{t:"\u03B1 and \u03B2 particles and the change of A and Z",what:"A parent and a final nucleus are given. Find the number of \u03B1 and \u03B2 particles emitted, or the daughter nucleus after a decay.",steps:["n\u03B1 = \u0394A/4.","Z\u2032 = Z \u2212 2n\u03B1 + n\u03B2.","Gamma emission changes nothing."],ex:"\xB2\xB3\u2078U \u2192 \xB2\u2070\u2076Pb: 8 \u03B1 and 6 \u03B2.",tp:"decay"},{t:"Parallel and successive decay",what:"A nucleus decays by two routes, or a daughter is formed from a parent. Find the effective half-life, the fraction by one route, or the ratio of the numbers at equilibrium.",steps:["Parallel: \u03BB = \u03BB\u2081 + \u03BB\u2082.","Fraction by route 1: \u03BB\u2081/\u03BB.","Equilibrium: \u03BB\u2081N\u2081 = \u03BB\u2082N\u2082."],ex:"T\u2081 = 20 min, T\u2082 = 30 min: T = 12 min.",tp:"decay"}],guide:{intro:"Atoms and Nuclei is a high-scoring and quick chapter in JEE Mains: 2 or 3 questions almost every year, mostly short numerical questions. The favourites are the energy levels of hydrogen and hydrogen-like ions, spectral series and the number of lines, binding energy and the Q value, radioactive decay with half-life and activity, and the number of \u03B1 and \u03B2 particles. Learn the formulas of Bohr and of decay by heart and practise the ratio questions; about 7 hours spread over 5 days is enough.",plan:[["Day 1 \xB7 75 min","Rutherford\u2019s model, closest approach and impact parameter, Bohr\u2019s postulates, r, v and E of the nth orbit, ratio questions."],["Day 2 \xB7 75 min","Rydberg formula, the series, number of lines, ionisation and excitation energy, photon and electron collisions, hydrogen-like ions."],["Day 3 \xB7 75 min","Composition of the nucleus, radius and density, mass defect, binding energy and its curve, nuclear forces."],["Day 4 \xB7 75 min","Q value, fission and the reactor, fusion, then the decay law, half-life, mean life and activity."],["Day 5 \xB7 90 min","\u03B1, \u03B2 and \u03B3, counting particles, parallel and successive decay; then the Most asked types and a mock test."]],basics:["Coulomb\u2019s law and electric potential energy of two charges, U = kq\u2081q\u2082/r.","Circular motion and the centripetal force, mv\xB2/r.","Energy in electron-volt and the conversion 1 eV = 1.6 \xD7 10\u207B\xB9\u2079 J.","Photon energy E = hf = 1240/\u03BB (nm) eV.","The exponential function and the natural logarithm, ln 2 = 0.693.","Conservation of momentum and of energy in a two-body split."],path:[{t:"Step 1 \xB7 Rutherford and Bohr (Day 1)",d:"Learn the observations of the scattering experiment, r\u2080, b and the three formulas r, v and E for the nth orbit.",ready:"you can find r, v and E for He\u207A in n = 3 without a hint.",go:"formulas"},{t:"Step 2 \xB7 Spectrum and levels (Day 2)",d:"Learn the Rydberg formula, the five series with their regions, the count of lines and the excitation rules.",ready:"you can name the series of a line, give its longest and shortest wavelength, and count the lines from n = 5.",go:"formulas"},{t:"Step 3 \xB7 The nucleus (Day 3)",d:"Learn A, Z, N, the radius formula, the constant density, 1 u = 931.5 MeV and the properties of the nuclear force.",ready:"you can find the binding energy of a nucleus from its atomic mass and read the BE curve.",go:"notes"},{t:"Step 4 \xB7 Fission and fusion (Day 4)",d:"Learn the Q value from BE, the energy of a fission and of a fusion, and the parts of a reactor.",ready:"you can find the energy from 1 kg of uranium and the Q of d + t in under two minutes.",go:"formulas"},{t:"Step 5 \xB7 Radioactivity (Day 4\u20135)",d:"Learn N = N\u2080e^(\u2212\u03BBt), T, \u03C4, A, the number of \u03B1 and \u03B2 and parallel decay.",ready:"you can find the fraction left after any time and the numbers of \u03B1 and \u03B2 for a chain.",go:"asked"},{t:"Step 6 \xB7 Practise, then test",d:"Practise by question type, then take the mock test.",ready:"you score 8 out of 10 in practice twice in a row.",go:"practice"}],think:["Which part is this: scattering, Bohr\u2019s model, spectrum, energy levels, the nucleus, BE, fission or fusion, or decay?","For hydrogen-like ions, write Z first and mark which quantity is proportional to Z\xB2 or Z.","For a ratio between two orbits or two atoms, write the quantity in terms of n and Z and cancel the constants.","Energy in eV: use 13.6 and 1240; energy in MeV and u: use 931.5.","In a spectrum question, find the lower level n\u2081 (the series) and then the upper one.","For the decay law, count the half-lives first. If t/T is not a whole number, use the exponential.","Check A and Z on both sides of every nuclear equation."],watch:["The energy of a level is negative; the ionisation energy is positive and equals \u2212E.","Excitation energy is a difference of two levels, not the energy of the upper level.","A photon is absorbed only for an exact gap, but an electron can pass on a part of its energy.","Number of lines from the level n is n(n \u2212 1)/2; one atom gives at most n \u2212 1 photons.","For He\u207A and Li\xB2\u207A the radius has Z in the denominator and the energy has Z\xB2 in the numerator.","The nuclear density is the same for all nuclei; do not divide by A again.","Use the mass of the hydrogen atom (not the proton) with atomic masses in the mass defect, so that the electrons cancel.","The half-life of a mixture in parallel decay is less than both; add the \u03BB, not the T."],myths:[["Myth: In Rutherford\u2019s experiment all \u03B1 particles are deflected a lot.","Truth: Most go straight through; only about 1 in 8000 is deflected through a large angle."],["Myth: The electron in a Bohr orbit radiates because it accelerates.","Truth: Bohr assumed no radiation in a stationary orbit; light is emitted only in a jump between orbits."],["Myth: The total energy of the electron is positive because the kinetic energy is positive.","Truth: E = \u2212K is negative, since the potential energy is \u22122K. A negative E means the electron is bound."],["Myth: The speed of the electron increases with n.","Truth: v \u221D Z/n, so it decreases as the orbit becomes bigger."],["Myth: The ionisation energy of hydrogen is the energy of the ground state, \u221213.6 eV.","Truth: It is the energy needed to remove the electron, +13.6 eV."],["Myth: Any photon of more than 10.2 eV can excite the atom from n = 1 to n = 2.","Truth: A photon is absorbed only at the exact gap of 10.2 eV (or at more than 13.6 eV to ionise)."],["Myth: A heavier nucleus is always more stable because its binding energy is bigger.","Truth: Stability depends on BE per nucleon, which is highest near iron."],["Myth: The density of a large nucleus is greater than that of a small one.","Truth: R\xB3 \u221D A, so the density is constant for all nuclei."],["Myth: After two half-lives all the nuclei have decayed.","Truth: One fourth is still left after two half-lives; a half-life is the time for half of the remainder to decay."],["Myth: Heating the sample or compressing it changes the rate of radioactive decay.","Truth: \u03BB does not depend on temperature, pressure or chemical form."]]},extra:[]}})()})();
